import * as T from 'three';
import {RGBELoader} from './assets/RGBELoader.js';
export async function surfaces(scene,renderer,materials,sky){
 const loader=new T.TextureLoader();
 await Promise.all(Object.entries(materials).map(async([name,material])=>{const maps=await Promise.all(['color','normal','rough'].map(k=>loader.loadAsync(`./assets/terrain/${name}-${k}.jpg`)));maps.forEach((tx,i)=>{tx.wrapS=tx.wrapT=T.RepeatWrapping;tx.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());if(i===0)tx.colorSpace=T.SRGBColorSpace;if(name==='grass')tx.repeat.set(155,155);});material.color.set('white');material.map=maps[0];material.normalMap=maps[1];material.roughnessMap=maps[2];material.normalScale.setScalar(name==='asphalt'?.35:.7);material.roughness=1;material.needsUpdate=true;}));
 const hdr=await new RGBELoader().loadAsync('./assets/terrain/sunset.hdr');hdr.mapping=T.EquirectangularReflectionMapping;scene.environment=hdr;scene.environmentIntensity=.8;scene.background=hdr;scene.backgroundIntensity=.8;scene.backgroundBlurriness=.025;scene.remove(sky);
}
export async function foliage(scene,positions){const tex=await new T.TextureLoader().loadAsync('./assets/terrain/stone-pine.png');tex.colorSpace=T.SRGBColorSpace;const material=new T.MeshStandardMaterial({map:tex,alphaTest:.48,side:T.DoubleSide,roughness:1});const geo=new T.PlaneGeometry(1,1);geo.translate(0,.5,0);const forest=new T.InstancedMesh(geo,material,positions.length*2),dummy=new T.Object3D();positions.forEach((p,i)=>{for(let k=0;k<2;k++){dummy.position.set(p.x,p.y,p.z);dummy.scale.setScalar(p.s*2.5);dummy.rotation.y=i*2.399+k*Math.PI/2;dummy.updateMatrix();forest.setMatrixAt(i*2+k,dummy.matrix);}});forest.castShadow=true;forest.receiveShadow=true;scene.add(forest);}
export function furniture(scene,at,length){const steel=new T.MeshStandardMaterial({color:'#7e858a',roughness:.4,metalness:.8}),rubber=new T.MeshStandardMaterial({color:'#181b1e',roughness:.94});const dummy=new T.Object3D();const tires=new T.InstancedMesh(new T.TorusGeometry(.38,.17,8,16),rubber,360);for(let i=0;i<360;i++){const a=at(.27+Math.floor(i/3)*.00055);dummy.position.copy(a.p).addScaledVector(a.n,-14.5);dummy.position.y+=.22+(i%3)*.3;dummy.rotation.set(Math.PI/2,0,0);dummy.scale.setScalar(1);dummy.updateMatrix();tires.setMatrixAt(i,dummy.matrix);}tires.castShadow=tires.receiveShadow=true;scene.add(tires);
 const points=[];for(const side of [-1,1])for(let i=0;i<Math.floor(length/7);i++){const a=at(i/Math.floor(length/7)),b=at((i+1)/Math.floor(length/7));const p=a.p.clone().addScaledVector(a.n,side*17),q=b.p.clone().addScaledVector(b.n,side*17);points.push(p.clone().add(new T.Vector3(0,1,0)),p.clone().add(new T.Vector3(0,3.2,0)));for(const h of [1.3,1.8,2.3,2.8,3.2])points.push(p.clone().add(new T.Vector3(0,h,0)),q.clone().add(new T.Vector3(0,h,0)));}scene.add(new T.LineSegments(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color:'#6e7779',transparent:true,opacity:.5})));
 for(let i=0;i<14;i++){const a=at(i*.007),p=a.p.clone().addScaledVector(a.n,20);const pole=new T.Mesh(new T.CylinderGeometry(.09,.14,10,10),steel);pole.position.copy(p).y+=5;pole.castShadow=true;scene.add(pole);const lamp=new T.Mesh(new T.BoxGeometry(1.8,.18,.65),new T.MeshStandardMaterial({color:'#ededda',emissive:'#ffe4b0',emissiveIntensity:1.2}));lamp.position.copy(p).y+=10;scene.add(lamp);}
}
